new_urls=[]
for d in TX_COUNTIES:
    sources=[
        ('Texas Commission on Environmental Quality — Getting a Permit for an OSSF',TX_STATE),
        ('Texas Commission on Environmental Quality — OSSF Licensing',TX_LICENSES),
    ] + d['sources']
    sections=[
        ('Texas permitting framework','Texas requires applicants to work with the local permitting authority where an authorized local OSSF program exists. TCEQ notes that local programs can be more stringent than statewide minimums, so county-specific procedures control within the county program’s jurisdiction.')
    ] + d['sections']
    new_urls.append(write_county_page('Texas','texas',d['county'],d['authority'],d['contact'],sections,sources,verified='August 29, 2026'))

sitemap=OUTPUT/'sitemap.xml'
if sitemap.exists():
    sm=sitemap.read_text(encoding='utf-8')
    entries=''.join(f'<url><loc>{u}</loc><lastmod>2026-08-29</lastmod></url>' for u in new_urls if u not in sm)
    if entries:
        sitemap.write_text(sm.replace('</urlset>',entries+'</urlset>'),encoding='utf-8')

print(f'Texas additional expansion complete: +{len(new_urls)} verified county guides')
